<?php
require_once __DIR__.'/../config/config.php';$user=require_employee_user();$pdo=db();$employee=employee_owner($pdo,$user);$counts=[];foreach(['My Documents'=>['SELECT COUNT(*) FROM employee_documents WHERE employee_id=?',[$employee['id']]],'Pending Requests'=>["SELECT COUNT(*) FROM profile_change_requests WHERE employee_id=? AND status='PENDING'",[$employee['id']]],'Approved Requests'=>["SELECT COUNT(*) FROM profile_change_requests WHERE employee_id=? AND status='APPROVED'",[$employee['id']]],'Rejected Requests'=>["SELECT COUNT(*) FROM profile_change_requests WHERE employee_id=? AND status='REJECTED'",[$employee['id']]]] as $label=>$item){$q=$pdo->prepare($item[0]);$q->execute($item[1]);$counts[$label]=(int)$q->fetchColumn();}$requests=$pdo->prepare('SELECT id,requested_field,status,created_at,review_reason FROM profile_change_requests WHERE employee_id=? ORDER BY created_at DESC LIMIT 5');$requests->execute([$employee['id']]);$requests=$requests->fetchAll();$notifications=$pdo->prepare('SELECT * FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 5');$notifications->execute([$user['id']]);$notifications=$notifications->fetchAll();$pageTitle='My dashboard';require __DIR__.'/../includes/header.php';?><div class="mb-7"><p class="text-sm text-slate-500">Employee self-service</p><h1 class="font-display text-3xl font-bold mt-1">Welcome, <?=e($employee['first_name'])?></h1><p class="text-slate-500 mt-1"><?=e($employee['employee_number'].' · '.$employee['department_name'].' · '.$employee['position_name'])?></p></div><div class="grid grid-cols-2 xl:grid-cols-4 gap-4 mb-7"><?php foreach($counts as $label=>$count):?><div class="metric-card bg-white rounded-xl border border-slate-200 p-5"><p class="text-xs uppercase tracking-wide text-slate-500 font-bold"><?=e($label)?></p><p class="font-display text-3xl font-bold mt-3"><?=e($count)?></p></div><?php endforeach;?></div><div class="grid xl:grid-cols-2 gap-6"><section class="bg-white border rounded-xl p-6"><div class="flex justify-between"><h2 class="font-display text-xl font-bold">Recent requests</h2><a href="requests.php" class="text-sm font-bold text-teal-700">View all</a></div><?php foreach($requests as $request):?><div class="border-b py-4"><div class="flex justify-between"><b><?=e(ucwords(str_replace('_',' ',$request['requested_field'])))?></b><span class="text-xs font-bold"><?=e($request['status'])?></span></div><p class="text-xs text-slate-400 mt-1"><?=e($request['created_at'])?> <?= $request['review_reason']?'· '.e($request['review_reason']):''?></p></div><?php endforeach;?><?php if(!$requests):?><p class="text-sm text-slate-500 mt-5">No profile requests yet.</p><?php endif;?></section><section class="bg-white border rounded-xl p-6"><h2 class="font-display text-xl font-bold">Notifications</h2><?php foreach($notifications as $notification):?><div class="border-b py-4"><b><?=e($notification['title'])?></b><p class="text-sm text-slate-600 mt-1"><?=e($notification['message'])?></p><p class="text-xs text-slate-400 mt-1"><?=e($notification['created_at'])?></p></div><?php endforeach;?><?php if(!$notifications):?><p class="text-sm text-slate-500 mt-5">No notifications.</p><?php endif;?></section></div><?php require __DIR__.'/../includes/footer.php';